"""Stripe payment webhook endpoint (Flask)."""

import logging
import os

import stripe
from flask import Flask, jsonify, request

logger = logging.getLogger(__name__)

app = Flask(__name__)
endpoint_secret = os.getenv("STRIPE_WEBHOOK_SECRET", "")
store = {}


def handle_success(payment_intent):
    logger.info("Payment succeeded: %s", payment_intent.get("id"))
    # TODO: mark order paid, provision access, send receipt.


def handle_failure(payment_intent):
    logger.info("Payment failed: %s", payment_intent.get("id"))
    # TODO: update order status and notify the customer.


HANDLERS = {
    "payment_intent.succeeded": handle_success,
    "payment_intent.payment_failed": handle_failure,
}


@app.route("/webhook", methods=["POST"])
def webhook():
    payload = request.get_data()
    signature = request.headers.get("Stripe-Signature", "")

    try:
        event = stripe.Webhook.construct_event(payload, signature, endpoint_secret)
    except ValueError:
        return jsonify(error="invalid payload"), 400
    except stripe.error.SignatureVerificationError:
        return jsonify(error="invalid signature"), 400

    event_id = event.get("id")
    if event_id in store:
        return jsonify(received=True), 200

    handler = HANDLERS.get(event.get("type"))
    if handler:
        handler(event["data"]["object"])
        store[event_id] = True

    return jsonify(received=True), 200


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    app.run(host="0.0.0.0", port=int(os.getenv("PORT", "5000")))
